import React, { useState, useEffect, useMemo } from 'react';
import ReportViewer from './ReportViewer.jsx';
import { Search, ArrowUpDown, TrendingUp, TrendingDown, Minus, ChevronRight, RefreshCw, AlertCircle } from 'lucide-react';

const LOGO_SRC = "data:image/png;base64,";

const STATUS_STYLE = {
  'Improving': { dot: 'bg-emerald-600', text: 'text-emerald-800', bg: 'bg-emerald-50' },
  'Untapped': { dot: 'bg-amber-500', text: 'text-amber-800', bg: 'bg-amber-50' },
  'Exposed': { dot: 'bg-slate-500', text: 'text-slate-700', bg: 'bg-slate-100' },
  'Plateauing': { dot: 'bg-sky-500', text: 'text-sky-800', bg: 'bg-sky-50' },
  'Regression Risk': { dot: 'bg-rose-600', text: 'text-rose-800', bg: 'bg-rose-50' },
};

function StatusPill({ status }) {
  const s = STATUS_STYLE[status] || { dot: 'bg-stone-400', text: 'text-stone-700', bg: 'bg-stone-100' };
  return (
    <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium ${s.bg} ${s.text}`}>
      <span className={`w-1.5 h-1.5 rounded-full ${s.dot}`} />
      {status}
    </span>
  );
}

function RankBadge({ rank }) {
  if (rank == null) return <div className="w-9 h-9 flex items-center justify-center text-stone-300 text-xs">—</div>;
  const isElite = rank <= 20;
  return (
    <div className={`w-9 h-9 rounded-full flex items-center justify-center font-bold text-sm border-2 flex-shrink-0
      ${isElite ? 'bg-[#1BBFA8] border-[#1BBFA8] text-[#08131F]' : 'bg-[#F0EEE8] border-[#C9C4B8] text-[#3A362E]'}`}>
      {rank}
    </div>
  );
}

function ValueIndicator({ value }) {
  if (value == null) return <span className="text-stone-300 text-sm">—</span>;
  const isPositive = value > 0;
  const isNeutral = Math.abs(value) < 1;
  const Icon = isNeutral ? Minus : isPositive ? TrendingUp : TrendingDown;
  const color = isNeutral ? 'text-stone-400' : isPositive ? 'text-emerald-700' : 'text-rose-700';
  return (
    <span className={`inline-flex items-center gap-1 font-mono text-sm ${color}`}>
      <Icon size={13} />
      {value > 0 ? '+' : ''}{value}
    </span>
  );
}

export default function StrideLabDashboard() {
  const [horses, setHorses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [search, setSearch] = useState('');
  const [sortKey, setSortKey] = useState('Horse');
  const [sortDir, setSortDir] = useState('asc');
  const [statusFilter, setStatusFilter] = useState('All');
  const [selected, setSelected] = useState(null);
  const [reportHorse, setReportHorse] = useState(null);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/dashboard');
      if (!res.ok) throw new Error(`Server responded ${res.status}`);
      const data = await res.json();
      setHorses(data.filter(h => h.Runs && h.Runs > 0));
      setLastUpdated(new Date());
    } catch (err) {
      setError(err.message || 'Could not load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadData(); }, []);

  const statuses = ['All', 'Improving', 'Untapped', 'Exposed', 'Plateauing', 'Regression Risk'];

  const filtered = useMemo(() => {
    let rows = horses.filter(h => (h.Horse || '').toLowerCase().includes(search.toLowerCase()));
    if (statusFilter !== 'All') rows = rows.filter(h => h['Development Status'] === statusFilter);
    rows = [...rows].sort((a, b) => {
      let av = a[sortKey], bv = b[sortKey];
      if (av == null) av = sortDir === 'asc' ? Infinity : -Infinity;
      if (bv == null) bv = sortDir === 'asc' ? Infinity : -Infinity;
      if (typeof av === 'string') { av = av.toLowerCase(); bv = bv.toLowerCase(); }
      if (av < bv) return sortDir === 'asc' ? -1 : 1;
      if (av > bv) return sortDir === 'asc' ? 1 : -1;
      return 0;
    });
    return rows;
  }, [horses, search, sortKey, sortDir, statusFilter]);

  const toggleSort = (key) => {
    if (sortKey === key) setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    else { setSortKey(key); setSortDir('asc'); }
  };

  const SortHeader = ({ label, sortField }) => (
    <th
      onClick={() => toggleSort(sortField)}
      className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[#6B6560] cursor-pointer select-none hover:text-[#08131F] transition-colors"
    >
      <span className="inline-flex items-center gap-1">
        {label}
        <ArrowUpDown size={11} className={sortKey === sortField ? 'text-[#1BBFA8]' : 'text-[#C9C4B8]'} />
      </span>
    </th>
  );

  const topRated = [...horses].filter(h => h.Rank).sort((a,b) => a.Rank - b.Rank)[0];
  const improvingCount = horses.filter(h => h['Development Status'] === 'Improving').length;
  const untappedCount = horses.filter(h => h['Development Status'] === 'Untapped').length;

  return (
    <div className="min-h-screen bg-[#F5F3ED]" style={{ fontFamily: 'system-ui, sans-serif' }}>
      {/* Header */}
      <div className="bg-[#08131F] text-white border-b-4 border-[#1BBFA8]">
        <div className="max-w-6xl mx-auto px-5 py-5">
          <div className="flex items-center justify-between flex-wrap gap-4">
            <img src={LOGO_SRC} alt="The Stride Lab" className="h-12 w-auto" />
            <div className="flex items-center gap-4">
              <button
                onClick={loadData}
                disabled={loading}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded border border-[#2A3B4A] text-[#7FDDD0] text-xs hover:bg-[#122436] transition-colors disabled:opacity-50"
              >
                <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
                {loading ? 'Refreshing...' : 'Refresh'}
              </button>
              <div className="flex gap-6 text-sm">
                <div className="text-right">
                  <div className="text-[#8A9199] text-[10px] uppercase tracking-wide">Top Rated</div>
                  <div className="text-white font-bold">{topRated?.Horse || '—'}</div>
                </div>
                <div className="text-right">
                  <div className="text-[#8A9199] text-[10px] uppercase tracking-wide">Improving</div>
                  <div className="text-[#1BBFA8] font-bold">{improvingCount}</div>
                </div>
                <div className="text-right">
                  <div className="text-[#8A9199] text-[10px] uppercase tracking-wide">Untapped</div>
                  <div className="text-[#F2C14E] font-bold">{untappedCount}</div>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div className="max-w-6xl mx-auto px-5 pb-3 flex items-center justify-between">
          <p className="text-[#8A9199] text-xs">Dashboard &mdash; {horses.length} horses tracked</p>
          {lastUpdated && (
            <p className="text-[#8A9199] text-xs">Last updated {lastUpdated.toLocaleTimeString()}</p>
          )}
        </div>
      </div>

      {error && (
        <div className="max-w-6xl mx-auto px-5 pt-4">
          <div className="flex items-start gap-2 bg-rose-50 border border-rose-200 text-rose-800 text-sm rounded-lg px-4 py-3">
            <AlertCircle size={16} className="mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium">Could not load live data</p>
              <p className="text-rose-600 text-xs mt-0.5">{error}</p>
            </div>
          </div>
        </div>
      )}

      {/* Controls */}
      <div className="max-w-6xl mx-auto px-5 pt-5 pb-3">
        <div className="flex flex-wrap gap-3 items-center">
          <div className="relative flex-1 min-w-[200px]">
            <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9A9488]" />
            <input
              type="text"
              placeholder="Search horses..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full pl-9 pr-3 py-2 rounded border border-[#C9C4B8] bg-white text-[#08131F] text-sm focus:outline-none focus:ring-2 focus:ring-[#1BBFA8] focus:border-transparent"
            />
          </div>
          <div className="flex gap-1.5 flex-wrap">
            {statuses.map(s => (
              <button
                key={s}
                onClick={() => setStatusFilter(s)}
                className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-colors
                  ${statusFilter === s
                    ? 'bg-[#08131F] text-white border-[#08131F]'
                    : 'bg-white text-[#3A362E] border-[#C9C4B8] hover:border-[#1BBFA8]'}`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="max-w-6xl mx-auto px-5 pb-10">
        <div className="bg-white rounded-lg border border-[#E4E0D3] overflow-hidden shadow-sm">
          {loading && horses.length === 0 ? (
            <div className="px-4 py-16 text-center text-sm text-[#9A9488]">
              <RefreshCw size={20} className="animate-spin mx-auto mb-3 text-[#1BBFA8]" />
              Loading live data from your Stride Lab sheet...
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-[#EDEAE0] border-b-2 border-[#C9C4B8]">
                  <tr>
                    <SortHeader label="Rank" sortField="Rank" />
                    <SortHeader label="Horse" sortField="Horse" />
                    <SortHeader label="Runs" sortField="Runs" />
                    <SortHeader label="Current OR" sortField="Current OR" />
                    <SortHeader label="Stride Lab Rating" sortField="Stride Lab Rating" />
                    <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[#6B6560]">Ceiling</th>
                    <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[#6B6560]">Status</th>
                    <SortHeader label="Value" sortField="Value Index" />
                    <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[#6B6560]"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#EDEAE0]">
                  {filtered.map((h) => (
                    <React.Fragment key={h.Horse}>
                      <tr
                        onClick={() => setReportHorse(h.Horse)}
                        className={`cursor-pointer transition-colors hover:bg-[#FAF9F5] ${selected === h.Horse ? 'bg-[#F0EEE4]' : ''}`}
                      >
                        <td className="px-4 py-2.5"><RankBadge rank={h.Rank} /></td>
                        <td className="px-4 py-2.5 font-semibold text-[#08131F]">{h.Horse}</td>
                        <td className="px-4 py-2.5 text-sm text-[#6B6560] font-mono">{h.Runs}</td>
                        <td className="px-4 py-2.5 text-sm font-mono">
                          {h['Current OR'] ?? <span className="text-stone-300">—</span>}
                        </td>
                        <td className="px-4 py-2.5 text-sm font-semibold text-[#08131F] font-mono">
                          {h['Stride Lab Rating'] ?? <span className="text-stone-300">—</span>}
                        </td>
                        <td className="px-4 py-2.5 text-sm text-[#6B6560] font-mono">{h['Projected Ceiling']}</td>
                        <td className="px-4 py-2.5"><StatusPill status={h['Development Status']} /></td>
                        <td className="px-4 py-2.5"><ValueIndicator value={h['Value Index']} /></td>
                        <td className="px-4 py-2.5">
                          <ChevronRight size={16} className={`text-[#C9C4B8] transition-transform ${selected === h.Horse ? 'rotate-90' : ''}`} />
                        </td>
                      </tr>
                      {selected === h.Horse && (
                        <tr className="bg-[#FAF9F5]">
                          <td colSpan={9} className="px-4 py-4">
                            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 max-w-2xl">
                              <div>
                                <div className="text-xs uppercase tracking-wide text-[#9A9488]">Current Ability</div>
                                <div className="font-mono text-sm text-[#08131F] mt-0.5">{h['Current Ability']}</div>
                              </div>
                              <div>
                                <div className="text-xs uppercase tracking-wide text-[#9A9488]">Confidence</div>
                                <div className="font-mono text-sm text-[#08131F] mt-0.5">{h['Confidence']}</div>
                              </div>
                              <div>
                                <div className="text-xs uppercase tracking-wide text-[#9A9488]">Suggested Trip</div>
                                <div className="font-mono text-sm text-[#08131F] mt-0.5">{h['Suggested Trip']}</div>
                              </div>
                              <div>
                                <div className="text-xs uppercase tracking-wide text-[#9A9488]">Suggested Ground</div>
                                <div className="font-mono text-sm text-[#08131F] mt-0.5">{h['Suggested Ground']}</div>
                              </div>
                            </div>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  ))}
                </tbody>
              </table>
              {filtered.length === 0 && !loading && (
                <div className="px-4 py-10 text-center text-sm text-[#9A9488]">
                  No horses match &ldquo;{search}&rdquo;
                </div>
              )}
            </div>
          )}
        </div>
      </div>
      {reportHorse && <ReportViewer horse={reportHorse} onClose={() => setReportHorse(null)} />}
    </div>
  );
}
